sys_script_include.script:
var ChangeRiskAjax = Class.create();
ChangeRiskAjax.prototype = {
    initialize: function() {
    },

    checkDangerSignals: function() {
        var ciId = this.getParameter('sysparm_ci_id');

        var result = {
            hasP1: false,
            hasFailedChange: false
        };

        var incidents = new GlideRecord('incidents');
        incidents.addQuery('cmdb_ci', ciId);
        incidents.addQuery('active', true);
        incidents.addQuery('priority', 1); 
        incidents.setLimit(1); 
        incidents.query();

        if (incidents.hasNext()) {
            result.hasP1 = true;
        }

        var changeRequest = new GlideRecord('change_request');
        changeRequest.addQuery('cmdb_ci', ciId);
        changeRequest.addQuery('active', false); 
        changeRequest.addEncodedQuery('close_code=unsuccessful^closed_atONLast 7 days@javascript:gs.beginningOfLast7Days()@javascript:gs.endOfLast7Days()');

        changeRequest.setLimit(1);
        changeRequest.query();

        if (changeRequest.hasNext()) {
            result.hasFailedChange = true;
        }

        return JSON.stringify(result);
    },

    type: 'ChangeRiskAjax'
};
